(defn run!
  [arguments {:keys [resolve-operation print-diagnostic! exit!]}]
  (try
    (when-not (dispatch/dispatch! resolve-operation arguments)
      (binding [*out* *err*]
        (println usage-text))
      (exit! 2))
    (shutdown-agents)
    (catch clojure.lang.ExceptionInfo exception
      (print-diagnostic! exception)
      (exit! 1))))
